CREATE DATABASE IF NOT EXISTS smart_invest CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;USE smart_invest;
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,referral_code VARCHAR(20) NOT NULL UNIQUE,referred_by_user_id BIGINT UNSIGNED NULL,balance DECIMAL(14,2) NOT NULL DEFAULT 0,referral_earnings DECIMAL(14,2) NOT NULL DEFAULT 0,status ENUM('active','suspended') NOT NULL DEFAULT 'active',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_users_referrer FOREIGN KEY(referred_by_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS plans(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(50) NOT NULL,amount DECIMAL(14,2) NOT NULL,daily_rate DECIMAL(6,2) NOT NULL DEFAULT 0,duration_days INT NOT NULL DEFAULT 30,active BOOLEAN NOT NULL DEFAULT TRUE);
INSERT INTO plans(name,amount,daily_rate,duration_days) VALUES('Plan 1',50,10,30),('Plan 2',100,10,30),('Plan 3',250,10,30),('Plan 4',500,10,30),('Plan 5',1000,10,30),('Plan 6',2000,10,30),('Plan 7',3000,10,30) ON DUPLICATE KEY UPDATE name=VALUES(name);
CREATE TABLE IF NOT EXISTS payment_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,plan_id INT UNSIGNED NOT NULL,amount DECIMAL(14,2) NOT NULL,transaction_id VARCHAR(100) NULL UNIQUE,payment_screenshot VARCHAR(255) NULL,status ENUM('pending','approved','rejected') NOT NULL DEFAULT 'pending',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at TIMESTAMP NULL,CONSTRAINT fk_payment_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_payment_plan FOREIGN KEY(plan_id) REFERENCES plans(id));
CREATE TABLE IF NOT EXISTS investments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,plan_id INT UNSIGNED NOT NULL,amount DECIMAL(14,2) NOT NULL,daily_rate DECIMAL(6,2) NOT NULL,duration_days INT NOT NULL,status ENUM('active','completed') NOT NULL DEFAULT 'active',start_at DATETIME NOT NULL,end_at DATETIME NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_invest_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_invest_plan FOREIGN KEY(plan_id) REFERENCES plans(id));
CREATE TABLE IF NOT EXISTS withdrawals(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(14,2) NOT NULL,method VARCHAR(40) NOT NULL,account VARCHAR(1000) NOT NULL,status ENUM('pending','completed','rejected') NOT NULL DEFAULT 'pending',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,reviewed_at TIMESTAMP NULL,CONSTRAINT fk_withdraw_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
